    for r in range(1, H-1):
        if grid_in[r][0] == 1:
            corners.append((r, 0))
    for r in range(1, H-1):
        if grid_in[r][W-1] == 1:
            corners.append((r, W-1))

    print(f"Found {len(corners)} corners: {corners}")

    if len(corners) < 4:
        print("Not enough corners to proceed")
        return output

    # Determine cross positions
    corner_cols = [c[1] for c in corners]
    col_counts = {}
    for c in corner_cols:
        col_counts[c] = col_counts.get(c, 0) + 1
    c_cross = max(col_counts, key=col_counts.get)

    corner_rows = [c[0] for c in corners]
    row_counts = {}
    for r in corner_rows:
        row_counts[r] = row_counts.get(r, 0) + 1
    r_cross = max(row_counts, key=row_counts.get)

    print(f"Cross at row {r_cross}, col {c_cross}")

    # Fill cross
    for c in range(W):
        output[r_cross][c] = 1
    for r in range(H):
        output[r][c_cross] = 1

    # Top corner Bethesda (if top corner exists)
    top_corners = [c for c in corners if c[0] == 0]
    if top_corners:
        cr, cc = top_corners[0]
        for r in range(cr + 2, min(H, cr + 6)):
            for c in range(cc - 1, cc + 4):
                if 0 <= r < H and 0 <= c < W:
                    if grid_in[r][c] == 2:
                        output[r][c] = 1

    # Bottom corner Bethesda
    bottom_corners = [c for c in corners if c[0] == H-1]
    if bottom_corners:
        cr, cc = bottom_corners[0]
        for r in range(cr - 6, cr - 3):
            for c in range(cc - 1, cc + 4):
                if 0 <= r < H and 0 <= c < W:
                    if grid_in[r][c] == 2:
                        output[r][c] = 1

    # Left corner Bethesda
    left_corners = [c for c in corners if c[1] == 0]
    if left_corners:
        cr, cc = left_corners[0]
        for r in range(cr - 1, cr + 2):
            for c in range(cc + 2, cc + 6):
                if 0 <= r < H and 0 <= c < W:
                    if grid_in[r][c] == 2:
                        output[r][c] = 1

    # Right corner Bethesda
    right_corners = [c for c in corners if c[1] == W-1]
    if right_corners:
        cr, cc = right_corners[0]
        for r in range(cr + 1, cr + 3):
            for c in range(cc - 8, cc - 4):
                if 0 <= r < H and 0 <= c < W:
                    if grid_in[r][c] == 2:
                        output[r][c] = 1

    return output

