    row = test_in[r]
    if 1 in row:
        for c in range(len(row)):
            if row[c] == 1:
                corners.append((r, c))
                print(f"  Corner at (r{r}, c{c})")

print(f"\nTotal corners: {len(corners)}")

print("\nGrouping by column:")
